namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(
        IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        ArgumentNullException.ThrowIfNull(items);
        ArgumentNullException.ThrowIfNull(supplier);

        var plan = new List<string>();
        foreach (var item in items)
        {
            if (!TryGetOrderQuantity(item, season, out var quantity))
                continue;

            bool placed = supplier.PlaceOrder(item.Sku, quantity);
            plan.Add(FormatResult(item.Sku, quantity, placed));
        }
        return plan;
    }

    private static bool TryGetOrderQuantity(
        StockItem item, int season, out int quantity)
    {
        quantity = 0;
        if (item.OnHand < 0 || string.IsNullOrEmpty(item.Sku))
            return false;

        int deficit = item.ReorderPoint - (item.OnHand - item.Reserved);
        quantity = ApplySeason(CalculateBaseQuantity(deficit), season);
        return quantity > 0;
    }

    private static int CalculateBaseQuantity(int deficit) => deficit switch
    {
        <= 0 => 0,
        < 10 => 10,
        < 100 => deficit,
        _ => deficit + 50
    };

    private static int ApplySeason(int quantity, int season) => season switch
    {
        4 when quantity > 0 => (int)(quantity * 1.5),
        1 => quantity / 2,
        _ => quantity
    };

    private static string FormatResult(string sku, int quantity, bool placed) =>
        !placed ? $"{sku}:FAILED" :
        quantity > 200 ? $"{sku}:LARGE:{quantity}" : $"{sku}:{quantity}";
}
